{
  "schema_version": 1,
  "notice": "Offline client guidance only: no registry, credentials or runner was inspected. Use hello for actual runner capabilities and authority.",
  "topic": {
    "name": "runners",
    "summary": "Select a runner and inspect its identity, authority and fleet.",
    "commands": [
      {
        "name": "runners",
        "effect": "Read saved runner connections locally."
      },
      {
        "name": "hello",
        "effect": "Contact one selected runner for identity, mode, role and features."
      },
      {
        "name": "snapshot",
        "effect": "Read the selected runner's instances and operation receipts."
      },
      {
        "name": "inventory",
        "effect": "Contact all enrolled runners; watch reports each independently."
      },
      {
        "name": "enroll",
        "effect": "Verify and save a new runner connection."
      },
      {
        "name": "runner-edit",
        "effect": "Verify the same runner at a new endpoint and update local enrollment."
      },
      {
        "name": "forget",
        "effect": "Remove local enrollment; does not stop its ships."
      }
    ],
    "guidance": [
      "Start with --config-dir REGISTRY runners. Then put --config-dir REGISTRY --runner NAME --expected-runner-id ID before hello and snapshot, using the saved runner_id.",
      "Unreachable is not stopped. A desktop profile does not isolate the runner's ships. Honor excluded ships and hosts without probing them.",
      "An identity mismatch requires resolving the intended runner; do not overwrite enrollment to suppress it. hello, not this guide, establishes supported features and authority."
    ]
  },
  "next": [
    "urbit-collector COMMAND --help",
    "urbit-collector help"
  ]
}

{
  "schema_version": 1,
  "notice": "Offline client guidance only: no registry, credentials or runner was inspected. Use hello for actual runner capabilities and authority.",
  "topic": {
    "name": "ships",
    "summary": "Observe and operate ships managed by a selected runner.",
    "commands": [
      {
        "name": "snapshot",
        "effect": "Read desired/observed state, revisions, recovery status and operation receipts."
      },
      {
        "name": "watch",
        "effect": "Poll snapshots until canceled; JSON output is NDJSON."
      },
      {
        "name": "logs",
        "effect": "Read a bounded runtime log tail with operator authority."
      },
      {
        "name": "operate",
        "effect": "Submit an explicit start, stop, maintenance or import-recovery operation."
      },
      {
        "name": "configure",
        "effect": "Change requested runtime settings at an expected revision."
      },
      {
        "name": "create-fake",
        "effect": "Register a fresh fake; boot occurs on explicit Start."
      },
      {
        "name": "create-ship",
        "effect": "Stage a keyed identity and boot material; boot occurs on explicit Start."
      },
      {
        "name": "create-comet",
        "effect": "Register a new comet configuration; mining/networking occurs on explicit Start."
      }
    ],
    "guidance": [
      "Pin --runner NAME --expected-runner-id ID and inspect hello/snapshot. Bind actions to instance ID and current config_revision; the instance name need not be the Urbit identity.",
      "Read operate --help, then use operate INSTANCE start|stop --revision N --request-id ID for the authorized action. Submission success is not completion: follow that exact operation in snapshot until terminal, then check resulting state.",
      "After a revision conflict, refresh and review the intended effect. After a lost acknowledgement, retain the original request ID and reconcile its receipt; do not guess by retrying with a new ID.",
      "Logs may contain sensitive data. Ordinary status does not require login-code or credentials. For hosted Eyre sessions, see help connections."
    ]
  },
  "next": [
    "urbit-collector COMMAND --help",
    "urbit-collector help"
  ]
}

{
  "schema_version": 1,
  "notice": "Offline client guidance only: no registry, credentials or runner was inspected. Use hello for actual runner capabilities and authority.",
  "topic": {
    "name": "imports",
    "summary": "Review a stopped pier, import it and resolve retained recovery state.",
    "commands": [
      {
        "name": "piers",
        "effect": "Inspect pier discovery on the selected runner."
      },
      {
        "name": "preview-pier",
        "effect": "Inspect a stopped source and derive identity, destination and fingerprint."
      },
      {
        "name": "import-pier",
        "effect": "Move/copy the reviewed source into managed storage; completion stays stopped."
      },
      {
        "name": "snapshot",
        "effect": "Read import progress, terminal result and retained recovery evidence."
      },
      {
        "name": "operate",
        "effect": "Explicitly recover a retained import, or Start after reviewing stopped completion."
      },
      {
        "name": "enroll-pier",
        "effect": "Register a discovered stopped pier or relink a moved registered pier."
      },
      {
        "name": "move-pier",
        "effect": "Move a stopped registered pier without replacing a destination."
      }
    ],
    "guidance": [
      "Pin the selected runner and use preview-pier --help. Source paths belong to that runner host, not the collector machine. Inspect only the authorized stopped source.",
      "Review the derived instance/ship/network, fingerprint, exclusive instance parent and named pier child. Use import-pier --help for the reviewed inputs and --confirm-stopped; that flag does not stop a running ship.",
      "Preserve a rejected source. Use its quoted entry/check to diagnose ownership, links, mounts or file types; do not recursively chmod/chown or delete lock files as a repair.",
      "Follow the exact operation receipt. Retained-source or recovery-required state needs its specific recovery action and current revision; do not delete the source, overwrite a destination or restart blindly.",
      "Successful import stays stopped and may have identity_pending. Explicit Start is a separate operation that verifies the running identity."
    ]
  },
  "next": [
    "urbit-collector COMMAND --help",
    "urbit-collector help"
  ]
}

{
  "schema_version": 1,
  "notice": "Offline client guidance only: no registry, credentials or runner was inspected. Use hello for actual runner capabilities and authority.",
  "topic": {
    "name": "connections",
    "summary": "Sign in to an Eyre ship or approve an independent plugin session.",
    "commands": [
      {
        "name": "ships",
        "effect": "Read locally enrolled Eyre connections; no runner is required."
      },
      {
        "name": "ship-enroll",
        "effect": "Save an origin-bound Eyre connection and expected ship identity."
      },
      {
        "name": "ship-login",
        "effect": "Read +code from stdin, verify identity and save a session."
      },
      {
        "name": "ship-status",
        "effect": "Check the enrolled ship/session against Eyre."
      },
      {
        "name": "ship-logout",
        "effect": "Revoke the selected collector session."
      },
      {
        "name": "app-plugins",
        "effect": "Inspect locally installed connection-helper declarations without executing them."
      },
      {
        "name": "app-connections",
        "effect": "Read durable application attempts locally."
      },
      {
        "name": "app-connect",
        "effect": "Issue and hand off an independent session to the exact approved plugin/profile."
      },
      {
        "name": "app-disconnect",
        "effect": "Revoke only the selected application attempt's session."
      },
      {
        "name": "app-recover",
        "effect": "Recover an interrupted attempt without retrying issuance or delivery."
      },
      {
        "name": "app-reconcile",
        "effect": "Clean the selected receiver state after confirmed revocation."
      },
      {
        "name": "app-archive",
        "effect": "Archive a fully closed/reconciled attempt while retaining its replay receipt."
      },
      {
        "name": "app-connection",
        "effect": "Read one active or archived request locally."
      }
    ],
    "guidance": [
      "Use --config-dir REGISTRY, without --runner or --socket. Hosted ships work independently of runner enrollment. Put the login code on stdin with ship-login NAME --code-stdin; never in arguments or reports.",
      "Before app-connect, read ships, app-plugins and app-connections. Its --help specifies the exact ship ID/revision, plugin/profile/artifact, request ID and broad-session acknowledgement.",
      "Each plugin receives a separate ordinary Eyre session. Eyre does not isolate desks. Plugins send data directly to the ship and retain standalone URL/+code sign-in; Omabit is not their data proxy.",
      "On uncertain results, inspect the durable request before recovery. Do not replay approval. Disconnect/recover/reconcile require the attempt's current revision; archive retains permanent replay protection."
    ]
  },
  "next": [
    "urbit-collector COMMAND --help",
    "urbit-collector help"
  ]
}

{
  "schema_version": 1,
  "notice": "Offline client guidance only: no registry, credentials or runner was inspected. Use hello for actual runner capabilities and authority.",
  "topic": {
    "name": "hosting",
    "summary": "Inspect runner hosting evidence and separate repair from observation.",
    "commands": [
      {
        "name": "hello",
        "effect": "Read the selected runner's capabilities and access role."
      },
      {
        "name": "host-check",
        "effect": "Read cached native-package and live private-engine compatibility evidence."
      },
      {
        "name": "snapshot",
        "effect": "Read runtime, operation and recovery status."
      }
    ],
    "guidance": [
      "Use host-check --help with a pinned runner. The collector needs no local Docker access. A successful report does not itself qualify hosting or repair a failed check.",
      "Installation, local package verification/repair and qualification are separate urbit-runner commands with different effects; read that binary's help before using them.",
      "Qualification creates disposable runtime resources. Use only the authorized host/test boundary; do not substitute the active engine or inspect excluded ships. A profile alone does not isolate host services."
    ]
  },
  "next": [
    "urbit-collector COMMAND --help",
    "urbit-collector help"
  ]
}
